--
-- Table structure for table `bus_locations`
--

DROP TABLE IF EXISTS `bus_locations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bus_locations` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `session_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `license_plate` varchar(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `bus_line_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `driver_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bus_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `location` point NOT NULL /*!80003 SRID 4326 */,
  `speed` decimal(5,2) NOT NULL,
  `heading_towards` decimal(5,2) NOT NULL,
  `timestamp` datetime(3) NOT NULL,
  `received_at` datetime(3) NOT NULL DEFAULT (utc_timestamp(3)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `telemetry_sample_once` (`session_id`,`timestamp`,`bus_status`),
  KEY `bus_line_id` (`bus_line_id`),
  KEY `driver_id` (`driver_id`),
  KEY `bus_locations_latest` (`license_plate`,`timestamp` DESC),
  KEY `bus_locations_session` (`session_id`,`timestamp` DESC),
  SPATIAL KEY `bus_locations_geo` (`location`),
  CONSTRAINT `bus_locations_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `driver_sessions` (`id`),
  CONSTRAINT `bus_locations_ibfk_2` FOREIGN KEY (`license_plate`) REFERENCES `license_plates` (`plate`),
  CONSTRAINT `bus_locations_ibfk_3` FOREIGN KEY (`bus_line_id`) REFERENCES `bus_lines` (`id`),
  CONSTRAINT `bus_locations_ibfk_4` FOREIGN KEY (`driver_id`) REFERENCES `users` (`id`),
  CONSTRAINT `bus_locations_chk_1` CHECK ((`bus_status` in (_utf8mb4'circulating',_utf8mb4'notCirculating'))),
  CONSTRAINT `bus_locations_chk_2` CHECK ((`speed` between 0 and 80)),
  CONSTRAINT `bus_locations_chk_3` CHECK (((`heading_towards` >= 0) and (`heading_towards` < 360)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
